const uid = "opendt-topology";
const screens = [["opendt-overview", "Dashboard"], ["opendt-topology", "Topology"], ["opendt-tutorial", "Tutorial"]];
const windows = [["week", "Week"], ["day", "Day"], ["hours", "6 h"]];
const decisions = [["on", "On"], ["off", "Off"]];
const periods = [];
const plots = [];
const week = {"from": "2022-10-06T22:00:00.000Z", "to": "2022-10-13T22:00:00.000Z"};
// Grafana's own components (@grafana/ui) drawn in `node`, in Grafana's theme, anew at each call, e.g.
// render(node, (h, ui) => h(ui.Button, { onClick }, 'Apply')) with h being React.createElement; the node keeps its
// React root, so components in a panel whose content never changes (no {{...}}) stay over its refreshes
const render = (node, draw) =>
  Promise.all(['react', 'react-dom', '@grafana/ui'].map((name) => System.import(name))).then(([React, ReactDOM, ui]) => {
    node.root ??= ReactDOM.createRoot(node);
    node.root.render(React.createElement(ui.ThemeContext.Provider, { value: context.grafana.theme }, draw(React.createElement, ui)));
  });
// CSS for what lies outside the panel, added once to the page (the panel renders at every refresh), in the colours
// of Grafana's theme: var(--panel), var(--canvas), var(--line), and var(--ink)
const css = (id, text) => {
  const { background, border, text: ink } = context.grafana.theme.colors;
  const theme = ':root { --panel: ' + background.primary + '; --canvas: ' + background.canvas + '; --line: ' + border.medium + '; --ink: ' + ink.primary + ' }\n';
  document.getElementById(id) || document.head.insertAdjacentHTML('beforeend', '<style id="' + id + '">' + theme + text + '</style>');
};
// none of Grafana's own: no "Powered by Grafana" under the screen, no menus over the panels, and no empty box where
// the menu was (Grafana 12.4's test id; a box with the ⓘ of an untitled panel stays)
const grafana = [
  '[data-testid="public-dashboard-footer"]',
  '[data-testid$="hover-header-container"]:has([data-testid="title-items-container"]:empty)',
  'button[aria-label^="Menu for panel"]',
];
css('opendt-grafana', grafana.join(', ') + ' { display: none !important; }');
// light or dark, as last chosen in this browser; Grafana takes its theme from the address, when the page loads
const light = document.body.classList.contains('theme-light');
const theme = (name) => {
  const address = new URL(location.href);
  address.searchParams.set('theme', name);
  location.replace(address);
};
const chosen = localStorage.getItem('opendt-theme');
if (chosen && (chosen === 'light') !== light) theme(chosen);
// ☰ Plots opens the plots of the screen by row, ticked while shown, in Grafana's dialog: a tick shows or hides a plot
// at once, a row's tick all of its plots. The address keeps the hidden plots, so a plot added later shows, even with
// an old address. On the page, the dialog outlives the view's refreshes
const pick = () => {
  document.getElementById('opendt-plots') || document.body.insertAdjacentHTML('beforeend', '<div id="opendt-plots"></div>');
  const node = document.getElementById('opendt-plots');
  // kept here: Grafana's $hidden follows the address only at the view's next run
  let hidden = context.grafana.replaceVariables('$' + '{hidden:csv}').split(',');
  const close = () => render(node, () => null);
  const draw = () => render(node, (h, ui) => {
    // a tick for these plots: on while all of them show, a dash while some do
    const tick = (label, keys) => {
      const on = keys.filter((key) => !hidden.includes(key)).length;
      const show = ({ target }) => {
        hidden = hidden.filter((key) => !keys.includes(key)).concat(target.checked ? [] : keys);
        context.grafana.locationService.partial({ 'var-hidden': hidden }, true);
        draw();
      };
      return h(ui.Checkbox, { label, value: on === keys.length, indeterminate: on > 0 && on < keys.length, onChange: show });
    };
    const rows = plots.map(([row, shown]) => h(ui.Stack, { direction: 'column', alignItems: 'flex-start' },
      tick(h(ui.Text, { variant: 'h6' }, row), shown.map(([key]) => key)), ...shown.map(([key, title]) => tick(title, [key]))));
    return h(ui.Modal, { title: 'Plots shown', isOpen: true, onDismiss: close }, h(ui.Grid, { columns: 2, gap: 3 }, ...rows),
      h(ui.Modal.ButtonRow, null, h(ui.Button, { onClick: close }, 'Close')));
  });
