const progress = "http://localhost:3001/api/progress";
const style = "#opendt-start { position: fixed; inset: 0; z-index: 1000; background: var(--canvas); color: var(--ink);\n  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; }\n#opendt-start > div { width: 56%; }\n#opendt-start .bar [role=\"status\"] { height: 4px; }\n.opendt-start .doing { font-size: 17px; text-transform: uppercase; letter-spacing: 0.04em; text-align: center; }\n.opendt-start .tip { position: fixed; bottom: 12%; left: 0; right: 0; text-align: center; opacity: 0.65;\n  font-size: 17px; white-space: nowrap; }";
// CSS for what lies outside the panel, added once to the page (the panel renders at every refresh), in the colours
// of Grafana's theme: var(--panel), var(--canvas), var(--line), and var(--ink)
const css = (id, text) => {
  const { background, border, text: ink } = context.grafana.theme.colors;
  const theme = ':root { --panel: ' + background.primary + '; --canvas: ' + background.canvas + '; --line: ' + border.medium + '; --ink: ' + ink.primary + ' }\n';
  document.getElementById(id) || document.head.insertAdjacentHTML('beforeend', '<style id="' + id + '">' + theme + text + '</style>');
};
// none of Grafana's own: no "Powered by Grafana" under the screen, no menus over the panels, and no empty box where
// the menu was (Grafana 12.4's test id; a box with the ⓘ of an untitled panel stays)
const grafana = [
  '[data-testid="public-dashboard-footer"]',
  '[data-testid$="hover-header-container"]:has([data-testid="title-items-container"]:empty)',
  'button[aria-label^="Menu for panel"]',
];
css('opendt-grafana', grafana.join(', ') + ' { display: none !important; }');
// light or dark, as last chosen in this browser; Grafana takes its theme from the address, when the page loads
const light = document.body.classList.contains('theme-light');
const theme = (name) => {
  const address = new URL(location.href);
  address.searchParams.set('theme', name);
  location.replace(address);
};
const chosen = localStorage.getItem('opendt-theme');
if (chosen && (chosen === 'light') !== light) theme(chosen);
// Grafana's own components (@grafana/ui) drawn in `node`, in Grafana's theme, anew at each call, e.g.
// render(node, (h, ui) => h(ui.Button, { onClick }, 'Apply')) with h being React.createElement; the node keeps its
// React root, so components in a panel whose content never changes (no {{...}}) stay over its refreshes
const render = (node, draw) =>
  Promise.all(['react', 'react-dom', '@grafana/ui'].map((name) => System.import(name))).then(([React, ReactDOM, ui]) => {
    node.root ??= ReactDOM.createRoot(node);
    node.root.render(React.createElement(ui.ThemeContext.Provider, { value: context.grafana.theme }, draw(React.createElement, ui)));
  });
// Grafana's own loading bar (@grafana/ui's LoadingBar, as over a loading panel) moves while the twin starts; once the
// twin's first window is done, the page reloads to show the twin (the rows follow a variable read at load)
// the card, copied over the whole screen, which does not scroll until the page reloads: on the page, as a fixed
// element inside the panel would stay in the panel; the bar beside the copy, so a new copy does not restart it
css('opendt-start-css', 'html, body { overflow: hidden }\n' + style);
let screen = document.getElementById('opendt-start');
if (!screen) {
  screen = document.body.appendChild(document.createElement('div'));
  screen.id = 'opendt-start';
  screen.innerHTML = '<div></div><div class="bar"></div>';
  const bar = screen.lastChild;
  render(bar, (h, ui) => h(ui.LoadingBar, { width: bar.clientWidth, delay: 0 }));
}
const state = (window.opendtStart ??= { step: 0 });
// never a step back: once the twin's first window is done, the panel shows the card of before the API answered (step
// 1) until the page reloads
const step = Number(context.element.querySelector('.opendt-start').dataset.step);
if (step >= state.step) {
  state.step = step;
  screen.firstChild.innerHTML = context.element.innerHTML;
}
state.done ??= setInterval(() => {
  // the twin's time came after the panel had rendered, and hid its row: the twin runs, and the screen goes
  if (context.grafana.replaceVariables('$twin')) {
    clearInterval(state.done);
    clearInterval(state.ready);
    delete window.opendtStart;
    document.getElementById('opendt-start-css').remove();
    screen.remove();
  }
}, 200);
state.ready ??= setInterval(async () => {
  try {
    const { data } = await (await fetch(progress)).json();
    if (!data.length) location.reload();
  } catch {} // the API is not up yet
}, 3000);
